arguments.command:
cd /workspace/project && python3 - <<'EOF'
p='src/roce_packet.c'
s=open(p).read()
s=s.replace("""static uint32_t load24(const uint8_t *p) {
    return ((uint32_t)p[0] << 16) | ((uint32_t)p[1] << 8) | p[2];
}
""","")
s=s.replace("""    const size_t udp_off = ip_off + EPIC_IP_LEN;
    const size_t bth_off = udp_off + EPIC_UDP_LEN;
""","""    const size_t udp_off = ip_off + EPIC_IP_LEN;
""")
open(p,'w').write(s)
EOF
gcc -std=c11 -O2 -fPIC -Wall -Wextra -Iinclude -c src/roce_packet.c -o /tmp/rp.o && echo CLEAN
